const filename = env.get("SITE_CONFIG_PATH") || "/data/config/site.solis.json";
msg.filename = filename;
return msg;

const store = env.get("GLOBAL_STORE") || "default";

function fail(message) {
    node.status({ fill: "red", shape: "ring", text: message });
    return [null, { payload: { ok: false, error: message } }];
}

const cfg = msg.payload;
if (!cfg || typeof cfg !== "object") return fail("site config is not an object");
if (!cfg.site) return fail("missing site");
if (!Array.isArray(cfg.iec104Points)) return fail("missing iec104Points[]");
if (!Array.isArray(cfg.iec104Commands)) cfg.iec104Commands = [];
if (!Array.isArray(cfg.modbusReads)) cfg.modbusReads = [];
if (!cfg.mqttPayload) cfg.mqttPayload = { fields: [] };

const deviceId = cfg.site.deviceId || env.get("DEVICE_ID") || "DEVICE";
cfg.site.deviceId = deviceId;

function normalizePoint(p, isCommand) {
    const out = Object.assign({}, p);
    if (!isCommand && out.name && !String(out.name).startsWith(deviceId + "_")) {
        out.name = `${deviceId}_${out.name}`;
    }
    return out;
}

const points = cfg.iec104Points.map(p => normalizePoint(p, false));
const commands = cfg.iec104Commands.map(p => normalizePoint(p, true));
const templates = points.concat(commands);

global.set("siteConfig", cfg, store);
global.set("iec104_templates", templates, store);

// Also set without explicit store for compatibility with older nodes.
global.set("siteConfig", cfg);
global.set("iec104_templates", templates);

msg.siteConfig = cfg;
msg.iec104_templates = templates;
msg.payload = {
    ok: true,
    siteId: cfg.site.siteId,
    deviceId,
    pointCount: points.length,
    commandCount: commands.length,
    modbusReadCount: cfg.modbusReads.length
};

node.status({
    fill: "green",
    shape: "dot",
    text: `${deviceId}: ${templates.length} IEC104 mappings`
});

return [msg, null];
